import{_ as a,o as n,c as t,a2 as o}from"./chunks/framework.C7GIOALF.js";const p=JSON.parse('{"title":"Commander Supervillain Rumble","description":"","frontmatter":{},"headers":[],"relativePath":"formats/archenemy/variants/rumble-commander.md","filePath":"formats/archenemy/variants/rumble-commander.md","lastUpdated":null}'),r={name:"formats/archenemy/variants/rumble-commander.md"};function i(s,e,l,m,c,h){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="commander-supervillain-rumble" tabindex="-1">Commander Supervillain Rumble <a class="header-anchor" href="#commander-supervillain-rumble" aria-label="Permalink to &quot;Commander Supervillain Rumble&quot;">​</a></h1><p><a href="./../">Archenemy versions</a> · <strong>Rules: Commander free-for-all</strong></p><h2 id="players-and-materials" tabindex="-1">Players and materials <a class="header-anchor" href="#players-and-materials" aria-label="Permalink to &quot;Players and materials&quot;">​</a></h2><p>Play a free-for-all Commander game, normally with three or more players. Everyone has their own scheme deck.</p><p>Each player supplies a legal 100-card Commander deck, including its commander or commanders, with normal singleton and color-identity requirements. Each scheme deck contains <strong>at least ten cards, all with different English names</strong>.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Put commanders in the command zone and shuffle ordinary libraries.</li><li>Shuffle scheme decks separately and keep them face down in their owners&#39; command zones.</li><li>Set every player&#39;s individual life total to <strong>40</strong>.</li><li>Randomly choose the starting player.</li><li>Draw seven cards each and take normal multiplayer mulligans.</li></ol><p>The 60-life team setup from Archenemy Commander does not apply to this free-for-all version.</p><h2 id="turns-combat-and-commander-rules" tabindex="-1">Turns, combat, and Commander rules <a class="header-anchor" href="#turns-combat-and-commander-rules" aria-label="Permalink to &quot;Turns, combat, and Commander rules&quot;">​</a></h2><p>Take individual turns in normal turn order. Everyone is an opponent; nobody shares turns, life, or resources. The starting player draws on their first turn.</p><p>At the beginning of each player&#39;s precombat main phase, that player sets a scheme in motion. In the procedure below, “the archenemy” means that active player.</p><p>Attack any legal opponent or attackable object, assigning each attacker separately. Players may attack several opponents in one combat, but cannot block for another opponent. Commander tax, command-zone movement, and the 21-combat-damage loss condition from a single commander apply normally.</p><h2 id="setting-schemes-in-motion" tabindex="-1">Setting schemes in motion <a class="header-anchor" href="#setting-schemes-in-motion" aria-label="Permalink to &quot;Setting schemes in motion&quot;">​</a></h2><p>Keep the scheme deck shuffled, face down in the command zone, separate from the ordinary library. Its owner cannot inspect or rearrange it without an effect allowing that.</p><p>As the archenemy&#39;s precombat main phase begins on each of their turns, turn the top scheme face up in the command zone. This mandatory turn-based action sets the scheme in motion and does not use the stack. Abilities that trigger from it do use the stack, so players can respond to those abilities.</p><p>Choose targets when putting a triggered ability on the stack. Make choices or payments that the effect asks for during resolution at that time, rather than while revealing the scheme.</p><p>Schemes stay in the command zone. They are not battlefield permanents, cannot be cast, and cannot be destroyed with an effect that destroys a permanent. A face-up scheme&#39;s abilities function from the command zone.</p><h3 id="non-ongoing-schemes" tabindex="-1">Non-ongoing schemes <a class="header-anchor" href="#non-ongoing-schemes" aria-label="Permalink to &quot;Non-ongoing schemes&quot;">​</a></h3><p>A face-up, non-ongoing scheme goes face down on the bottom of its owner&#39;s scheme deck as a state-based action once no scheme triggered abilities are on the stack or waiting to be put there. Countering its ability does not leave the scheme permanently face up.</p><h3 id="ongoing-schemes" tabindex="-1">Ongoing schemes <a class="header-anchor" href="#ongoing-schemes" aria-label="Permalink to &quot;Ongoing schemes&quot;">​</a></h3><p>An ongoing scheme stays face up until an ability tells its controller to abandon it. Abandoning it turns it face down and puts it on the bottom of its owner&#39;s scheme deck. Its printed condition determines when that happens; revealing another scheme does not automatically abandon it.</p><p>Follow individual scheme instructions for additional schemes, costs, choices, and exceptions. A scheme asking an opponent to choose “self” or “others” still permits “others” when that opponent has no teammates, even if that option affects nobody.</p><h2 id="winning-losing-and-leaving" tabindex="-1">Winning, losing, and leaving <a class="header-anchor" href="#winning-losing-and-leaving" aria-label="Permalink to &quot;Winning, losing, and leaving&quot;">​</a></h2><p>Win by being the last remaining player or through a normal winning effect. Individual loss conditions include zero life, ten poison counters, drawing from an empty library, and 21 combat damage from a single commander.</p><p>When a player leaves, their owned objects, including schemes, leave under the ordinary multiplayer rules. Remaining players continue; if all remaining players lose together, the game is a draw.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="https://magic.wizards.com/en/formats/archenemy-commander" target="_blank" rel="noreferrer">Wizards&#39; Archenemy Commander page, Supervillain Rumble section</a> and <a href="https://magic.wizards.com/en/rules" target="_blank" rel="noreferrer">Comprehensive Rules</a> 903 and 904.</p>',27)])])}const u=a(r,[["render",i]]);export{p as __pageData,u as default};
